ALTER TABLE fid.fid_record_revisions ADD CONSTRAINT fid_record_revision_unique UNIQUE (target_contract, canonical_record_id, record_revision);
ALTER TABLE fid.fid_record_revisions ADD CONSTRAINT fid_predecessor_fk FOREIGN KEY (predecessor_persistence_id) REFERENCES fid.fid_record_revisions (persistence_id) ON UPDATE RESTRICT ON DELETE RESTRICT;
ALTER TABLE fid.fid_record_revisions ADD CONSTRAINT fid_revision_positive_check CHECK (record_revision >= 1);
ALTER TABLE fid.fid_record_revisions ADD CONSTRAINT fid_revision_shape_check CHECK ((record_revision = 1 AND predecessor_persistence_id IS NULL AND predecessor_record_id IS NULL AND predecessor_revision IS NULL) OR (record_revision > 1 AND predecessor_persistence_id IS NOT NULL AND predecessor_record_id IS NOT NULL AND predecessor_revision = record_revision - 1));
ALTER TABLE fid.fid_record_revisions ADD CONSTRAINT fid_relationship_projection_shape_check CHECK ((target_contract = 'FootballRelationship' AND relationship_source_contract IS NOT NULL AND relationship_source_record_id IS NOT NULL AND relationship_target_contract IS NOT NULL AND relationship_target_record_id IS NOT NULL AND relationship_type IS NOT NULL AND relationship_direction IS NOT NULL) OR (target_contract <> 'FootballRelationship' AND relationship_source_contract IS NULL AND relationship_source_record_id IS NULL AND relationship_target_contract IS NULL AND relationship_target_record_id IS NULL AND relationship_type IS NULL AND relationship_direction IS NULL));
ALTER TABLE fid.fid_persistence_idempotency ADD CONSTRAINT fid_persistence_idempotency_request_hash_unique UNIQUE (idempotency_key, request_hash);
ALTER TABLE fid.fid_persistence_batches ADD CONSTRAINT fid_batch_count_check CHECK (expected_operation_count >= 0 AND committed_operation_count >= 0 AND failed_operation_count >= 0);
ALTER TABLE fid.fid_persistence_batch_operations ADD CONSTRAINT fid_batch_operation_order_unique UNIQUE (batch_id, operation_index);
ALTER TABLE fid.fid_persistence_batch_operations ADD CONSTRAINT fid_batch_operation_batch_fk FOREIGN KEY (batch_id) REFERENCES fid.fid_persistence_batches (batch_id) ON DELETE CASCADE;
ALTER TABLE fid.fid_persistence_batch_operations ADD CONSTRAINT fid_batch_operation_index_check CHECK (operation_index >= 0);
ALTER TABLE fid.fid_persistence_effect_receipts ADD CONSTRAINT fid_effect_receipt_batch_fk FOREIGN KEY (batch_ref) REFERENCES fid.fid_persistence_batches (batch_id);
ALTER TABLE fid.fid_persistence_migrations ADD CONSTRAINT fid_schema_version_environment_unique UNIQUE (schema_version, deployment_environment);
